/** Shapes of the JSON generated by `python build.py` into public/. */

export type LocalizedText = Record<string, string>;

export interface IndexWork {
  id: string;
  type: string;
  year: number | null;
  available_languages: string[];
  titles?: LocalizedText;
  tags?: Record<string, string[]>;
}

export interface IndexAuthor {
  id: string;
  name: LocalizedText;
  works_count: number;
  works: IndexWork[];
}

export interface CorpusIndex {
  version: string;
  last_updated: string;
  authors: IndexAuthor[];
  statistics: {
    total_authors: number;
    total_works: number;
    total_translations: number;
    languages_with_content: string[];
  };
}

export interface AuthorInfo {
  id: string;
  names: LocalizedText;
  biography: LocalizedText;
  birth_year: number;
  death_year?: number | null;
  image_url?: string;
  external_links?: { wikipedia?: LocalizedText };
}

export interface WorkMeta {
  id: string;
  author_id: string;
  type: string;
  year_written?: number | null;
  year_published?: number | null;
  original_language: string;
}

export interface Stanza {
  type: 'stanza';
  number: number;
  lines: string[];
}

export interface Paragraph {
  type: 'paragraph';
  number: number;
  text: string;
}

export type Block = Stanza | Paragraph;

export interface Note {
  reference: string; // "stanza:2" | "paragraph:5"
  text: string;
}

export interface VocabEntry {
  word: string;
  lemma?: string;
  pos?: string;
  gloss: LocalizedText;
}

export interface WorkContent {
  language: string;
  work_id: string;
  author_id: string;
  title: string;
  content_type: 'poem' | 'prose';
  structure: 'stanzas' | 'paragraphs';
  content: Block[];
  translator: string | null;
  translation_year: number | null;
  orthography?: string | null;
  tags: string[];
  notes: Note[];
  vocabulary?: VocabEntry[];
}
